function build() {
  fs.mkdirSync(REVIEWS_DIR, { recursive: true });
  const args = process.argv.slice(2);
  let files = args.length ? args : fs.readdirSync(DATA_DIR).filter(f => f.endsWith('.json')).map(f => path.join(DATA_DIR, f));
  if (!files.length) {
    console.log('无复盘数据 JSON，跳过渲染');
    return;
  }
  const reports = [];
  for (const f of files) {
    const full = path.resolve(f);
    if (!fs.existsSync(full)) { console.error('文件不存在:', full); continue; }
    reports.push(JSON.parse(fs.readFileSync(full, 'utf8')));
  }
  reports.sort((a, b) => {
    const ka = `${a.meta.date}_${a.meta.time}`;
    const kb = `${b.meta.date}_${b.meta.time}`;
    return kb.localeCompare(ka);
  });

  const byDate = {};
  for (const r of reports) {
    const d = r.meta.date;
    if (!byDate[d]) byDate[d] = {};
    byDate[d][r.meta.type] = `reviews/${d}_${String(r.meta.time).replace(':', '-')}.html`;
  }
  const latest = reports.length ? `reviews/${reports[0].meta.date}_${String(reports[0].meta.time).replace(':', '-')}.html` : 'index.html';

  // 报告页位于 reviews/ 子目录,导航链接必须用 ../ 前缀,同目录报告去掉 reviews/
  const stripReviews = (p) => String(p || '').replace(/^reviews\//, '');
  // 全局最新各类型报告(跨日期),保证从任一报告页都能跳到最新午盘/收盘
  const latestOfType = (type) => {
    const r = reports.find(x => x.meta.type === type);
    if (!r) return '';
    return stripReviews(`reviews/${r.meta.date}_${String(r.meta.time).replace(':', '-')}.html`);
  };
  for (const report of reports) {
    const m = report.meta;
    const sameDay = byDate[m.date] || {};
    const nav = {
      home: '../index.html',
      midday: stripReviews(sameDay.midday) || latestOfType('midday') || '../index.html',
      close: stripReviews(sameDay.close) || latestOfType('close') || '../index.html',
      latest: stripReviews(latest)
    };
    const html = m.type === 'premarket' ? renderPremarketReport(report, nav) : renderReport(report, nav);
    const outName = `${m.date}_${String(m.time).replace(':', '-')}.html`;
    fs.writeFileSync(path.join(REVIEWS_DIR, outName), html, 'utf8');
    console.log('已生成:', outName);
  }
  fs.writeFileSync(path.join(SITE_DIR, 'index.html'), renderIndex(reports), 'utf8');
  console.log('已生成: index.html (共', reports.length, '份复盘)');

  const rankReport = reports.find(r => r.mainRank && r.mainRank.length);
  if (rankReport) {
    const rankNav = {
      home: 'index.html',
      midday: byDate[rankReport.meta.date] && byDate[rankReport.meta.date].midday || 'index.html',
      close: byDate[rankReport.meta.date] && byDate[rankReport.meta.date].close || 'index.html',
      latest: latest
    };
    fs.writeFileSync(path.join(SITE_DIR, 'main-rank.html'), renderMainRankPage(rankReport, rankNav), 'utf8');
    console.log('已生成: main-rank.html');
  }
}

build();

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = process.cwd();

console.log('Running build_report.js...');
try {
  console.log(execSync('node scripts/build_report.js', { cwd: ROOT, encoding: 'utf8' }));
} catch (e) {
  console.error('Build error:', e.stderr || e.message);
  process.exit(1);
}

const sharedJs = fs.readFileSync(path.join(ROOT, 'scripts/shared_client.js'), 'utf8').trim();
const modalCss = fs.readFileSync(path.join(ROOT, 'modal_css.txt'), 'utf8').trim();
const dragonCss = fs.readFileSync(path.join(ROOT, 'dragon_pool.css'), 'utf8').trim();
const intlCss = fs.readFileSync(path.join(ROOT, 'intl_mkt.css'), 'utf8').trim();
const tpCss = fs.readFileSync(path.join(ROOT, 'tech_playbook_verdict.css'), 'utf8').trim();
const ceCss = fs.readFileSync(path.join(ROOT, 'close_emotion.css'), 'utf8').trim();
const heroCss = fs.readFileSync(path.join(ROOT, 'hero_mobile.css'), 'utf8').trim();

// 自动扫描 site 下所有 HTML(含 reviews/ 子目录),云端新日期自动纳入
function scanFiles() {
  const out = [];
  const walk = (dir) => {
    const abs = path.join(ROOT, dir);
    if (!fs.existsSync(abs)) return;
    for (const name of fs.readdirSync(abs)) {
      const rel = dir + '/' + name;
      const full = path.join(ROOT, rel);
      const st = fs.statSync(full);
      if (st.isDirectory()) {
        walk(rel);
      } else if (name.endsWith('.html')) {
        out.push(rel);
      }
    }
  };
  walk('site');
  return out;
}

const files = scanFiles();

for (const rel of files) {
  const file = path.join(ROOT, rel);
  if (!fs.existsSync(file)) { console.log('MISSING:', rel); continue; }
  let c = fs.readFileSync(file, 'utf8');

  // 确保 HTML 有 <style></style> 占位符(build_report.js 不输出)
  if (!c.includes('</style>')) {
    if (c.includes('</title>')) {
      c = c.replace('</title>', '</title>\n<style></style>', 1);
    } else if (c.includes('</head>')) {
      c = c.replace('</head>', '<style></style>\n</head>', 1);
    }
  }

  // Ensure modal CSS exists (inject into first </style> if missing)
  if (!c.includes('.modal-mask{display:none')) {
    if (c.includes('</style>')) {
      c = c.replace('</style>', modalCss + '\n</style>', 1);
      console.log('  +modal CSS:', rel);
    }
  }
  // Ensure dragon pool CSS exists
  if (!c.includes('.dragon-pool{')) {
    if (c.includes('</style>')) {
      c = c.replace('</style>', dragonCss + '\n</style>', 1);
      console.log('  +dragon CSS:', rel);
    }
  }
  // Ensure intl mkt CSS exists
  if (!c.includes('.intl-mkt{')) {
    if (c.includes('</style>')) {
      c = c.replace('</style>', intlCss + '\n</style>', 1);
      console.log('  +intl CSS:', rel);
    }
  }
  // Ensure tech/playbook/verdict CSS exists
  if (!c.includes('.tech-card{')) {
  // Ensure close emotion CSS exists
  if (!c.includes('.close-emotion{')) {
  // Ensure hero/mobile CSS exists
  if (!c.includes('.hero-eyebrow{')) {
    if (c.includes('</style>')) {
      c = c.replace('</style>', heroCss + '\n</style>', 1);
      console.log('  +hero CSS:', rel);
    }
  }
    if (c.includes('</style>')) {
      c = c.replace('</style>', ceCss + '\n</style>', 1);
      console.log('  +ce CSS:', rel);
    }
  }
    if (c.includes('</style>')) {
      c = c.replace('</style>', tpCss + '\n</style>', 1);
      console.log('  +tp CSS:', rel);
    }
  }

  // Remove any existing shared blocks
  const re = /<script src="https:\/\/cdnjs\.cloudflare\.com\/ajax\/libs\/qrcodejs\/1\.0\.0\/qrcode\.min\.js"><\/script>\s*\n\s*<script>[\s\S]*?<\/script>\s*\n?/g;
  c = c.replace(re, '');

  // Inject before </body>
  if (c.includes('</body>')) {
    c = c.replace('</body>', sharedJs + '\n</body>');
    fs.writeFileSync(file, c, 'utf8');
    console.log('INJECTED:', rel);
  } else {
    console.log('NO </body>:', rel);
  }
}
console.log('Done.');

