.dp-sector{white-space:nowrap}
.dp-reason{font-size:10px;color:#555;line-height:1.4;max-width:140px}
.dp-price{font-size:11px;color:#333;white-space:nowrap}
.dp-volume{font-size:10px;color:#666;line-height:1.4}
.dp-cat-text{font-size:10px;color:#555;line-height:1.4}
.dp-cat-detail{font-size:11px;color:#c33}
.dp-atds{font-size:14px;font-weight:700;color:#c33;text-align:center}
.dp-pos{font-size:10px;color:#185FA5;background:#f0f5ff;padding:3px 6px;border-radius:8px}
.dp-btn{font-size:10px;padding:4px 10px;border-radius:14px;border:1px solid #ddd;background:#fff;color:#666;cursor:pointer;white-space:nowrap}
.dp-btn-primary{background:#fff;color:#c33;border-color:#c33;font-weight:600}
.dp-table-foot{font-size:10px;color:#999;margin-top:10px;padding:8px;background:#fafafa;border-radius:8px;line-height:1.5}
.dp-grid{display:grid;grid-template-columns:1fr;gap:12px;margin-bottom:12px}
.dp-block{padding:14px}
.dp-block-h{font-size:13px;font-weight:700;margin-bottom:4px}
.dp-block-sub{font-size:10px;color:#999;margin-bottom:10px}
.dp-sb-row{display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid #f8f8f8}
