.dp-sb-info{flex:1;min-width:0}
.dp-sb-name{font-size:11px;font-weight:600;display:block;line-height:1.2}
.dp-sb-count{font-size:9px;color:#999}
.dp-sb-leaders,.dp-sb-stocks{font-size:10px;color:#666;line-height:1.5;flex:1;min-width:0}
.dp-risk-list{font-size:11px;color:#555;line-height:1.6}
.dp-risk-note{font-size:10px;color:#999;display:block;margin-top:6px}
.dp-consec-row{display:flex;align-items:center;gap:8px;padding:6px 0;font-size:11px;line-height:1.4}
