.dp-consec-meta{color:#666;font-size:10px}
.dp-rules-card{padding:14px}
.dp-rules-h{font-size:13px;font-weight:700;margin-bottom:4px}
.dp-rules-sub{font-size:10px;color:#999;margin-bottom:12px;line-height:1.5}
.dp-rules-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.dp-rule{background:#fafafa;border-radius:10px;padding:10px 8px}
.dp-rule-id{font-size:10px;color:#c33;font-weight:700}
.dp-rule-name{font-size:11px;color:#333;margin:4px 0;line-height:1.3}
.dp-rule-effect{font-size:10px;color:#185FA5}
.dp-verdict-card{padding:14px;border-left:3px solid #c33}
.dp-verdict-h{font-size:11px;color:#c33;letter-spacing:0.5px;margin-bottom:8px;font-weight:600}
.dp-verdict-body{font-size:13px;color:#1d1d1f;line-height:1.6;margin-bottom:8px}
.dp-verdict-sub{font-size:10px;color:#999;line-height:1.5}
.dp-live-dot{color:#c33;margin:0 4px;display:inline-block;animation:dpBlink 1.5s ease-in-out infinite}
@keyframes dpBlink{0%,100%{opacity:1}50%{opacity:0.3}}
.dp-table-card .card-title{font-size:13px}
.dp-time-nav{display:flex;justify-content:center;gap:16px;margin-top:10px;font-size:12px;color:#666}
.dp-time-nav a{text-decoration:none;color:#666;padding:2px 0}

/* 技术研判 */
.tech-card{margin:14px 16px}.ta-header{margin-bottom:10px}.ta-eyebrow{font-size:10px;color:#185FA5;letter-spacing:1.5px}.ta-title{display:block;font-size:16px;font-weight:700;margin-top:2px}
.ta-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:8px}
.ta-table th{background:#f5f7fa;padding:6px 4px;text-align:left;color:#666;font-weight:600;font-size:10px}
.ta-table td{padding:8px 4px;border-top:1px solid #f0f0f0;vertical-align:top}
.ta-name{font-weight:700;color:#333}.ta-last{font-size:10px;color:#888;font-weight:400}
.ta-level{display:flex;align-items:baseline;gap:6px;margin-bottom:4px}
