.ta-level.ta-support b{color:#c33}
.ta-level.ta-pressure b{color:#185FA5}
.ta-label{font-size:10px;color:#888}
.ta-ma{display:flex;gap:6px;flex-wrap:wrap;font-size:10px;color:#666}
