.vol-item:last-child{border-bottom:none}
.trend-list{margin-top:6px}.trend-item{display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px dashed #f0f0f0;font-size:12px}
.trend-item:last-child{border-bottom:none}
.trend-pct{background:linear-gradient(90deg,#185FA5,#c33);color:#fff;font-weight:700;font-size:11px;padding:3px 8px;border-radius:10px;min-width:48px;text-align:center}
.trend-text{color:#333;flex:1}
.risk-list{margin-top:6px}.risk-item{display:flex;align-items:baseline;gap:6px;padding:6px 0;border-bottom:1px dashed #f0f0f0;font-size:12px}
.risk-item:last-child{border-bottom:none}
.risk-name{font-weight:700;color:#c33;min-width:120px;font-size:11px}
.risk-desc{color:#555;flex:1}

/* Playbook */
.playbook-card{margin:14px 16px}.pb-header{margin-bottom:10px}.pb-eyebrow{font-size:10px;color:#185FA5;letter-spacing:1.5px}.pb-title{display:block;font-size:16px;font-weight:700;margin-top:2px}
.pb-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px}
.pb-sec{background:#fff;border:1px solid #f0f0f0;border-radius:8px;padding:8px;margin-bottom:0}
.pb-sec-h{font-size:12px;font-weight:700;margin-bottom:6px;color:#333}
.pb-offense .pb-sec-h{color:#c33}
.pb-defense .pb-sec-h{color:#185FA5}
.pb-themes .pb-sec-h{color:#7B3F99}
.pb-pitfall .pb-sec-h{color:#888}
.pb-item{padding:5px 0;border-bottom:1px dashed #f0f0f0;font-size:11px}
.pb-item:last-child{border-bottom:none}
.pb-name{font-weight:700;color:#333;display:flex;align-items:baseline;gap:6px;flex-wrap:wrap}
.pb-count{font-size:10px;background:#fef0f0;color:#c33;padding:1px 5px;border-radius:8px;font-weight:400}
.pb-lead{font-size:10px;background:#f0f7ff;color:#185FA5;padding:1px 5px;border-radius:8px;font-weight:400}
.pb-stocks{font-size:10px;color:#888;font-weight:400}
.pb-logic{color:#555;margin-top:2px;line-height:1.4}
.pb-scenario{color:#888;margin-top:2px;font-size:10px}
.rhythm-item{display:flex;gap:8px;padding:6px 0;border-bottom:1px dashed #f0f0f0;font-size:11px;align-items:flex-start}
.rhythm-item:last-of-type{border-bottom:none}
.rhythm-time{background:#185FA5;color:#fff;font-size:10px;padding:3px 6px;border-radius:8px;white-space:nowrap;font-weight:700}
.rhythm-rule{color:#333;flex:1;line-height:1.5}
.rhythm-pos{background:#fef8e8;padding:8px;border-radius:8px;margin-top:8px;font-size:11px;line-height:1.5;color:#7a5f00}

/* Verdict */
.verdict-card{margin:14px 16px}.vd-header{margin-bottom:10px}.vd-eyebrow{font-size:10px;color:#185FA5;letter-spacing:1.5px}.vd-title{display:block;font-size:16px;font-weight:700;margin-top:2px}
.vd-card{padding:10px 12px;border-left:3px solid #ccc}
.vd-offense{border-left-color:#c33}.vd-defense{border-left-color:#185FA5}.vd-pitfall{border-left-color:#888}
.vd-h{font-size:13px;font-weight:700;margin-bottom:6px;color:#333}
.vd-body{font-size:12px;line-height:1.6;color:#555}
